const now = new Date();
const day = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - 1));
const rows = [];
for (let minuteOfDay = 0; minuteOfDay < 24 * 60; minuteOfDay += 15) {
  const instant = new Date(day.getTime() + minuteOfDay * 60_000);
  const stamp = instant.toISOString().slice(0, 19).replace(/[-:T]/g, '');
  const sourceUrl = `https://data.gdeltproject.org/gdeltv2/${stamp}.gkg.csv.zip`;
  const available = new Date(instant.getTime() + 15 * 60_000).toISOString();
  rows.push({ json: { source_id: 'gdelt-sentiment-prototype', source_url: sourceUrl, source_revision: `${stamp}.gkg.csv.zip`, observation_id: `gdelt-gkg-${stamp}`, observed_at_utc: instant.toISOString(), available_at_utc: available, query_definition_version: 'eurusd-context-terms.v1', uncertainty_label: 'EXPERIMENTAL_CONTEXT_ONLY' } });
}
return rows;

const { createHash } = require('crypto');
const terms = ['euro', 'eur', 'dollar', 'usd', 'currency', 'forex', 'ecb', 'federal reserve'];
const source = $('Build prior-day GKG URLs').item.json;
const binary = await this.helpers.getBinaryDataBuffer(0, 'data');
const buckets = new Map();
for (const line of binary.toString('utf8').split(/\r?\n/)) {
  const fields = line.split('\t');
  if (fields.length < 16) continue;
  if (!terms.some((term) => fields.slice(5, 15).join(' ').toLowerCase().includes(term))) continue;
  const tone = Number(fields[15].split(',', 1)[0]);
  const timestamp = fields[1] || '';
  if (!Number.isFinite(tone) || !/^\d{10}/.test(timestamp)) continue;
  const bucket = `${timestamp.slice(0, 8)}T${timestamp.slice(8, 10)}:00:00Z`;
  const values = buckets.get(bucket) || [];
  values.push(tone);
  buckets.set(bucket, values);
}
const payloadSha256 = `sha256:${createHash('sha256').update(binary).digest('hex')}`;
return [...buckets.entries()].map(([bucket_time_utc, tones]) => ({ json: { ...source, payload_sha256: payloadSha256, payload_path: `n8n://gdelt/${source.source_revision}`, retrieved_at_utc: new Date().toISOString(), bucket_time_utc, article_count: tones.length, mean_tone: tones.reduce((sum, tone) => sum + tone, 0) / tones.length } }));
